// Atajos de zonas y canales: el tipo completa la descripción (después se le
// agrega dónde va, ej. "PIR living") y el número siguiente se pone solo.
function siguienteNumeroInst(lista) {
  const nums = lista.map((z) => parseInt(z.numero, 10)).filter((n) => isFinite(n));
  return String(nums.length ? Math.max(...nums) + 1 : 1);
}
function prepararNumeroInst() {
  if (!instZonaNumeroInput.value.trim()) instZonaNumeroInput.value = siguienteNumeroInst(instZonasAgregadas);
  if (!instCanalNumeroInput.value.trim()) instCanalNumeroInput.value = siguienteNumeroInst(instCanalesAgregadas);
}
[["instZonaAtajos", () => instZonaNumeroInput, () => instZonaDescripcionInput, () => instZonasAgregadas],
 ["instCanalAtajos", () => instCanalNumeroInput, () => instCanalDescripcionInput, () => instCanalesAgregadas]].forEach(([id, num, desc, lista]) => {
  const cont = document.getElementById(id);
  if (!cont) return;
  cont.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => {
    if (!num().value.trim()) num().value = siguienteNumeroInst(lista());
    desc().value = b.dataset.txt + " ";
    desc().focus();
    try { desc().setSelectionRange(desc().value.length, desc().value.length); } catch (e) { /* nada */ }
  }));
});
instZonaDescripcionInput.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); agregarZonaBtn.click(); } });
instCanalDescripcionInput.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); agregarCanalBtn.click(); } });

guardarCanalesBtn.addEventListener("click", async () => {
  if (!instalacionActivaId) return;
  guardarCanalesBtn.disabled = true;
  try {
    const res = await fetch("/api/historial", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN },
      body: JSON.stringify({ accion: "guardar_items_instalacion", instalacion_id: instalacionActivaId, tipo: "canal", items: instCanalesAgregadas }),
    });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "Error desconocido");
    showToast(`${instCanalesAgregadas.length} canal(es) guardado(s).`);
  } catch (err) {
    showToast("No se pudo guardar: " + err.message);
  } finally {
    guardarCanalesBtn.disabled = false;
  }
});

function leerArchivoComoBase64Instalacion(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

// Las fotos de instalación se piden con el pase de la sesión: un <img src>
// común no lo manda, y desde el cambio de seguridad el servidor las
// rechazaba (se veían como imagen rota). Se bajan con fetch y se muestran
// desde la memoria del celular; quedan guardadas mientras la app esté abierta.
const fotosConPaseCache = new Map();
function urlFotoConPase(url) {
  if (fotosConPaseCache.has(url)) return fotosConPaseCache.get(url);
  const promesa = fetch(url, { headers: { Authorization: "Bearer " + SERVICIOS_API_TOKEN } })
    .then((r) => { if (!r.ok) throw new Error("HTTP " + r.status); return r.blob(); })
    .then((blob) => URL.createObjectURL(blob))
    .catch((err) => { fotosConPaseCache.delete(url); throw err; });
  fotosConPaseCache.set(url, promesa);
  return promesa;
}
function mostrarFotoConPase(img, url) {
  img.classList.add("foto-cargando");
  urlFotoConPase(url)
    .then((src) => { img.src = src; img.classList.remove("foto-cargando"); img.dataset.lista = "1"; })
    .catch(() => { img.classList.remove("foto-cargando"); img.classList.add("foto-error"); img.alt = "No se pudo cargar la foto"; });
}

function pintarFotosInstalacion(fotos) {
  const id = instalacionActivaId;
  instFotosGrid.innerHTML = "";
  fotos.forEach((nombre) => {
    const item = document.createElement("div");
    item.className = "instalacion-foto-item";
    item.innerHTML = `
      <img alt="Foto de la instalación" role="button" tabindex="0" title="Tocá para verla grande">
      <button type="button" class="instalacion-foto-borrar" title="Borrar">✕</button>
    `;
    const img = item.querySelector("img");
    mostrarFotoConPase(img, `/api/historial?tipo=foto-instalacion&id=${encodeURIComponent(id)}&nombre=${encodeURIComponent(nombre)}`);
    img.addEventListener("click", () => { if (img.dataset.lista) ampliarImagenParte(img.src); });
    item.querySelector("button").addEventListener("click", async (e) => {
      e.stopPropagation();
      if (!await confirmarApp("¿Borrar esta foto de la instalación?")) return;
      try {
        const res = await fetch("/api/historial", {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN },
          body: JSON.stringify({ accion: "borrar_foto_instalacion", instalacion_id: id, nombre }),
        });
        if (!res.ok) throw new Error("HTTP " + res.status);
        renderInstFotos();
      } catch (err) {
        showToast("No se pudo borrar la foto.");
      }
    });
    instFotosGrid.appendChild(item);
  });
  instFotosStatus.textContent = fotos.length ? `${fotos.length} foto${fotos.length === 1 ? "" : "s"} guardada${fotos.length === 1 ? "" : "s"}.` : "";
}

async function renderInstFotos() {
  if (!instalacionActivaId) return;
  try {
    const headers = { Authorization: "Bearer " + SERVICIOS_API_TOKEN };
    const res = await fetch(`/api/historial?tipo=instalacion&id=${instalacionActivaId}`, { headers, cache: "no-store" });
    const data = await res.json();
    if (!res.ok) return;
    pintarFotosInstalacion(data.fotos || []);
  } catch (err) {
    // si falla, se deja la grilla como estaba
  }
}

// Las fotos se achican antes de subirlas (una foto de celular pesa varios
// MB y el servidor rechaza envíos de más de ~4 MB: antes fallaban sin avisar).
instFotoInput.addEventListener("change", async () => {
  if (!instalacionActivaId) return;
  const archivos = Array.from(instFotoInput.files || []);
  if (archivos.length === 0) return;
  let fallidas = 0;
  for (let i = 0; i < archivos.length; i++) {
    instFotosStatus.textContent = `Subiendo foto ${i + 1} de ${archivos.length}...`;
    try {
      const base64 = await comprimirImagen(archivos[i], 1600, 0.75);
      const res = await fetch("/api/historial", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN },
        body: JSON.stringify({ accion: "subir_foto_instalacion", instalacion_id: instalacionActivaId, nombre_archivo: `foto-${Date.now()}-${i}.jpg`, base64 }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.ok === false) throw new Error(data.error || "HTTP " + res.status);
    } catch (err) {
      fallidas++;
    }
  }
  if (fallidas) showToast(fallidas === archivos.length ? "No se pudieron subir las fotos. Revisá la señal e intentá de nuevo." : `${fallidas} foto(s) no se pudieron subir. Probá de nuevo con esas.`);
  instFotoInput.value = "";
  renderInstFotos();
});

instalacionGuardarYCerrarBtn.addEventListener("click", async () => {
  if (!instalacionActivaId) return;
  instalacionGuardarYCerrarBtn.disabled = true;
  instalacionGuardarYCerrarBtn.textContent = "Guardando...";
  try {
    const headers = { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN };
    clearTimeout(instGuardadoTimers.zona);
    clearTimeout(instGuardadoTimers.canal);
    if (!(await guardarItemsInstalacion("zona")) || !(await guardarItemsInstalacion("canal"))) {
      throw new Error("no se pudieron guardar las zonas o los canales (¿sin señal?)");
    }
    // ---- El plano: después de cerrar ya no se puede agregar ni cambiar.
    const idInst = String(instalacionActivaId);
    const irAlPlano = () => document.getElementById("instPlanoCard").scrollIntoView({ behavior: "smooth", block: "start" });
    if (planosPendientesDe(idInst).length) await planosPendientesSubir();
    await instPlanoCargar();
    if (planosPendientesDe(idInst).length) {
      if (!await confirmarApp("Hay un plano de esta instalación que todavía no se subió (sin señal). Si cerrás ahora, ese plano se pierde.\n\n¿Cerrar igual?")) { irAlPlano(); return; }
      planosPendientesDe(idInst).forEach((p) => planosPendientesQuitar(p.uid));
    }
    let borradorInst = null;
    try { borradorInst = JSON.parse(localStorage.getItem(CQ_BORRADOR) || "null"); } catch (e) { borradorInst = null; }
    if (borradorInst && borradorInst.cambios && String(borradorInst.instalacion || "") === idInst) {
      if (!await confirmarApp("El croquis de esta instalación tiene cambios sin guardar en el servidor. Si cerrás ahora, esos cambios se pierden.\n\n¿Cerrar igual?", { aceptar: "Cerrar igual", cancelar: "Abrir el croquis para guardarlo" })) {
        cqAbrirEditor({ ...borradorInst, volverA: "instalacion" });
        return;
      }
    }
    const planos = instPlanoDeEsta();
    if (!planos.length) {
      if (PLANO_INSTALACION_OBLIGATORIO) { showToast("Para cerrar la instalación falta el plano: hacé el croquis o subí una foto del plano."); irAlPlano(); return; }
      if (!await confirmarApp("No cargaste el plano de la instalación (croquis o foto).\n\n¿Cerrar igual sin plano?")) { irAlPlano(); return; }
    }
    let planosPdf = [];
    if (planos.length) {
      instalacionGuardarYCerrarBtn.textContent = "Preparando el plano...";
      planosPdf = await instPlanosPdf(planos);
      instalacionGuardarYCerrarBtn.textContent = "Guardando...";
    }
    const simElegida = instSimElegida();
    if (simElegida && simElegida.error) { showToast(simElegida.error); document.getElementById("instSimCard").scrollIntoView({ behavior: "smooth", block: "center" }); return; }
    const datosSim = { ...instSimDatos() };
    const res = await fetch("/api/historial", { method: "POST", headers, body: JSON.stringify({ accion: "cerrar_instalacion", instalacion_id: instalacionActivaId, observaciones: instObservacionesInput.value.trim(), planos_pdf: planosPdf }) });
    const data = await res.json();
    if (!res.ok || !data.ok) {
      // Si el motivo es que falta marcar una salida, se manda de
      // vuelta a esa pantalla para que la marque — sin perder nada
      // de lo que ya cargó acá (zonas, canales, fotos y
      // observaciones quedan tal cual, para retomar el cierre
      // después sin tener que volver a escribir todo).
      if (data.error && data.error.includes("sin salida")) {
        showToast(data.error);
        instalacionAbiertaWrap.classList.remove("hidden");
        instalacionAbiertaWrap.scrollIntoView({ behavior: "smooth", block: "start" });
        actualizarEstadoDiaInstalacion();
        return;
      }
      throw new Error(data.error || "No se pudo cerrar");
    }
    const textoSim = await instSimRegistrar(simElegida, datosSim, idInst);
    showToast(textoSim ? `Instalación cerrada. ${textoSim}` : "Instalación cerrada correctamente.");
    // Sus planos quedan como registro (el servidor igual lo controla solo).
    try {
      await fetch("/api/datos?coleccion=croquis", { method: "POST", headers, body: JSON.stringify({ accion: "cerrar_instalacion", instalacion_id: String(instalacionActivaId) }) });
    } catch (e) { /* lo frena igual el servidor al querer guardar */ }
    try { const b = JSON.parse(localStorage.getItem(CQ_BORRADOR) || "null"); if (b && String(b.instalacion || "") === String(instalacionActivaId)) localStorage.removeItem(CQ_BORRADOR); } catch (e) { /* nada */ }
    resetearPantallaInstalacion();
    showScreen("home");
  } catch (err) {
    showToast("No se pudo cerrar: " + err.message);
  } finally {
    instalacionGuardarYCerrarBtn.disabled = false;
    instalacionGuardarYCerrarBtn.textContent = "✔ Guardar y cerrar instalación";
  }
});

// ---------- Plano de la instalación (croquis o foto del plano) ----------
// Queda atado a la instalación; al cerrarla ya no se puede cambiar.
const instPlanoLista = document.getElementById("instPlanoLista");
const instPlanoEstado = document.getElementById("instPlanoEstado");
let instPlanoIndice = [];
function instPlanoNum(v) { return String(v == null ? "" : v).replace(/\D/g, "").replace(/^0+/, ""); }
async function instPlanoCargar() {
  if (!instalacionActivaId || !instPlanoLista) return;
  const id = String(instalacionActivaId), dat = instalacionActivaDatos || {};
  try {
    const r = await fetch(`/api/datos?coleccion=croquis&instalacion=${encodeURIComponent(id)}&numero_cliente=${encodeURIComponent(dat.numero_cliente || "")}&cliente=${encodeURIComponent(dat.cliente || "")}`, { headers: { Authorization: "Bearer " + SERVICIOS_API_TOKEN }, cache: "no-store" });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || "HTTP " + r.status);
    if (String(instalacionActivaId) !== id) return;
    instPlanoIndice = Array.isArray(d) ? d : [];
    instPlanoRender();
    if (planosPendientesDe(id).length && navigator.onLine !== false) planosPendientesSubir();
    return true;
  } catch (err) {
    instPlanoRender();
    instPlanoEstado.textContent = "No se pudieron cargar los planos: " + err.message;
    return false;
  }
}
function instPlanoDeEsta() { return instPlanoIndice.filter((c) => String(c.instalacion || "") === String(instalacionActivaId)); }
function instPlanoRender() {
  const mios = instPlanoDeEsta();
  const pend = instalacionActivaId ? planosPendientesDe(instalacionActivaId) : [];
  instPlanoEstado.textContent = mios.length || pend.length ? "" : "Todavía no hay plano de esta instalación.";
  instPlanoLista.innerHTML = pend.map((p) => `<div class="historial-card cq-item cq-borrador">
      <div class="historial-card-cliente">${escapeHtml(p.titulo || "Foto del plano")} <span class="cq-etiqueta cq-etiqueta-cerrado">Sin subir</span></div>
      <div class="historial-card-horario">Quedó en el celular por falta de señal: se sube sola cuando vuelva.</div>
      <div class="cq-item-btns"><button type="button" class="btn btn-primary btn-small" data-reintentar="${escapeHtml(p.uid)}">Subir ahora</button><button type="button" class="btn btn-secondary btn-small cq-borrar" data-descartar="${escapeHtml(p.uid)}">Descartar</button></div>
    </div>`).join("") + mios.map((c, i) => `<div class="historial-card cq-item">
      <div class="historial-card-cliente">${escapeHtml(c.titulo || "Croquis")}${c.base ? ' <span class="cq-etiqueta cq-etiqueta-base">Sobre plano</span>' : ""}</div>
      <div class="historial-card-horario">${escapeHtml(c.autor || "")}${c.elementos ? " · " + c.elementos + " elementos" : ""}</div>
      <div class="cq-item-btns"><button type="button" class="btn btn-primary btn-small" data-abrir="${i}">Abrir</button>${!tecnicoLogueado || c.autor === tecnicoLogueado ? `<button type="button" class="btn btn-secondary btn-small cq-borrar" data-borrar="${i}">Borrar</button>` : ""}</div>
    </div>`).join("");
  instPlanoLista.querySelectorAll("[data-abrir]").forEach((b) => b.addEventListener("click", () => instPlanoAbrir(mios[Number(b.dataset.abrir)].id)));
  instPlanoLista.querySelectorAll("[data-reintentar]").forEach((b) => b.addEventListener("click", async () => {
    b.disabled = true; b.textContent = "Subiendo...";
    const n = await planosPendientesSubir();
    if (!n) showToast("Todavía no se pudo subir: revisá la señal.");
    instPlanoRender();
  }));
  instPlanoLista.querySelectorAll("[data-descartar]").forEach((b) => b.addEventListener("click", async () => {
    if (!await confirmarApp("¿Descartar este plano? No se sube y se borra del celular.")) return;
    planosPendientesQuitar(b.dataset.descartar);
    instPlanoRender();
  }));
  instPlanoLista.querySelectorAll("[data-borrar]").forEach((b) => b.addEventListener("click", async () => {
    const c = mios[Number(b.dataset.borrar)];
    if (!await confirmarApp(`¿Borrar "${c.titulo || "el plano"}" de esta instalación?`)) return;
    try {
      const r = await fetch("/api/datos?coleccion=croquis", { method: "POST", headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN }, body: JSON.stringify({ accion: "borrar", id: c.id }) });
      const d = await r.json().catch(() => ({}));
      if (!r.ok) throw new Error(d.error || "HTTP " + r.status);
      instPlanoIndice = instPlanoIndice.filter((x) => x.id !== c.id);
      instPlanoRender();
    } catch (err) { showToast("No se pudo borrar: " + err.message); }
  }));
}
async function instPlanoTraer(id) {
  const r = await fetch(`/api/datos?coleccion=croquis&id=${encodeURIComponent(id)}`, { headers: { Authorization: "Bearer " + SERVICIOS_API_TOKEN }, cache: "no-store" });
  const d = await r.json();
  if (!r.ok) throw new Error(d.error || "HTTP " + r.status);
  return d;
}
async function instPlanoAbrir(id) {
  try {
    const d = await instPlanoTraer(id);
    const dib = d.dibujo || {};
    cqAbrirEditor({ id: d.id, instalacion: d.instalacion || String(instalacionActivaId), soloLectura: !!d.cerrado, volverA: "instalacion", publicado: !!d.publicado, titulo: d.titulo, cliente: d.cliente, numero_cliente: d.numero_cliente, direccion: d.direccion, autor: d.autor, actualizado: d.actualizado, elementos: dib.elementos || [], fondo: dib.fondo || null, paginas: dib.paginas || null, medidas: !!dib.medidas });
  } catch (err) { showToast("No se pudo abrir: " + err.message); }
}
function instPlanoNuevo(paginas, titulo) {
  const dat = instalacionActivaDatos || {};
  cqAbrirEditor({ instalacion: String(instalacionActivaId), volverA: "instalacion", titulo: titulo || "Plano de la instalación", cliente: dat.cliente || instalacionClienteInput.value.trim(), numero_cliente: dat.numero_cliente || "", direccion: dat.direccion || instalacionDireccionInput.value.trim(), paginas: paginas || null, cambios: true });
  cqGuardarBorrador();
}
// Planos de Visio que la oficina ya tiene sincronizados para este cliente.
async function instPlanosVisioDelCliente() {
  const num = instPlanoNum((instalacionActivaDatos || {}).numero_cliente);
  if (!num) return [];
  try { await cargarPlanos(); } catch (e) { return []; }
  return (planosCache || []).filter((p) => p.numero_cliente && instPlanoNum(p.numero_cliente) === num).sort((a, b) => a.indice_plano - b.indice_plano);
}
document.getElementById("instPlanoCroquisBtn").addEventListener("click", async () => {
  if (!instalacionActivaId) return;
  const boton = document.getElementById("instPlanoCroquisBtn");
  boton.disabled = true;
  let visio = [];
  try { visio = await instPlanosVisioDelCliente(); } finally { boton.disabled = false; }
  const mios = instPlanoDeEsta().filter((c) => !c.cerrado);
  // Planos/croquis del mismo cliente hechos antes (por la oficina o en otra visita).
  // El plano de la última instalación cerrada va primero: una ampliación arranca desde ahí.
  const tiempo = (c) => { const f = fechaDelServidor(c.cerrado_en || c.actualizado); return f ? f.getTime() : 0; };
  const delCliente = instPlanoIndice.filter((c) => String(c.instalacion || "") !== String(instalacionActivaId))
    .sort((a, b) => (!!b.cerrado - !!a.cerrado) || (tiempo(b) - tiempo(a)));
  const ultimo = delCliente.find((c) => c.cerrado);
  if (!mios.length && !visio.length && !delCliente.length) { instPlanoNuevo(); return; }
  const capa = document.createElement("div");
  capa.className = "cq-datos-capa";
  capa.innerHTML = `<div class="cq-datos cq-menu">
    <h3>Plano de la instalación</h3>
    ${mios.map((c, i) => `<button type="button" class="btn btn-primary" data-seguir="${i}">${cqIc("lapiz")} Seguir «${escapeHtml(c.titulo || "Croquis")}»</button>`).join("")}
    ${delCliente.length || visio.length ? '<p class="pe-nota" style="margin:6px 0 2px;">Dibujar encima del plano de la casa:</p>' : ""}
    ${delCliente.map((c, i) => c === ultimo
      ? `<button type="button" class="btn ${mios.length ? "btn-secondary" : "btn-primary"} cq-plano-opcion" data-copiar="${i}">${cqIc("plano")}<span><b>Ampliar el plano de la última instalación</b><small>${escapeHtml(c.titulo || "Plano")}${tiempo(c) ? " · " + new Date(tiempo(c)).toLocaleDateString("es-AR") : ""} · lo anterior se ve atenuado</small></span></button>`
      : `<button type="button" class="btn btn-secondary" data-copiar="${i}">${cqIc("plano")} ${escapeHtml(c.titulo || "Croquis")}${c.base ? " (plano de la oficina)" : c.cerrado ? " (instalación anterior)" : ""}</button>`).join("")}
    ${visio.map((p, i) => `<button type="button" class="btn btn-secondary" data-visio="${i}">${cqIc("plano")} Plano de Visio del cliente${visio.length > 1 ? " " + (i + 1) : ""}</button>`).join("")}
    <button type="button" class="btn btn-secondary" data-blanco="1">${cqIc("nuevo")} Croquis en blanco</button>
    <button type="button" class="link-btn" data-cerrar="1">Cancelar</button>
  </div>`;
  document.body.appendChild(capa);
  capa.addEventListener("click", async (e) => {
    const b = e.target.closest("button");
    if (!b && e.target !== capa) return;
    capa.remove();
    if (!b || b.dataset.cerrar) return;
    if (b.dataset.blanco) { instPlanoNuevo(); return; }
    if (b.dataset.seguir) { instPlanoAbrir(mios[Number(b.dataset.seguir)].id); return; }
    if (b.dataset.copiar) {
      // Se dibuja sobre una copia: el plano original del cliente queda limpio para la próxima.
      try {
        const c = delCliente[Number(b.dataset.copiar)];
        const d = await instPlanoTraer(c.id);
        // Lo que ya estaba (de otra instalación) queda atenuado y bloqueado.
        const hayAntes = croquisPaginas(d.dibujo).some((p) => (p.elementos || []).length);
        const pags = croquisPaginas(d.dibujo).map((p) => ({ nombre: p.nombre || "Página 1", elementos: croquisMarcarComoAntes(p.elementos), fondo: p.fondo ? { ...p.fondo } : null }));
        instPlanoNuevo(pags, c.cerrado ? "Ampliación - " + String(c.titulo || "Plano").replace(/^(Ampliación|Instalación) - /, "") : "Instalación - " + (c.titulo || "Plano"));
        showToast(hayAntes ? "Lo que ya estaba instalado se ve atenuado. Dibujá lo nuevo encima; si algo de antes lo cambiaste, tocalo y «Es nuevo»." : "Dibujá encima lo que instalaste: el plano original queda como estaba.");
      } catch (err) { showToast("No se pudo abrir: " + err.message); }
      return;
    }
    if (b.dataset.visio) {
      const p = visio[Number(b.dataset.visio)];
      const carga = cqCapaCargando("Preparando el plano…", "Se trae el PDF del cliente y se pone de base.");
      try {
        const r = await fetch(`/api/planos?nombre=${encodeURIComponent(p.nombre)}`, { headers: { Authorization: "Bearer " + SERVICIOS_API_TOKEN } });
        if (!r.ok) throw new Error("No se pudo traer el plano");
        const blob = await r.blob();
        const plano = await cqPrepararPlano(new File([blob], p.nombre + ".pdf", { type: "application/pdf" }));
        carga.remove();
        instPlanoNuevo(plano.paginas, "Plano de la instalación");
        cqAvisoPlanoEditable(plano, "Plano del cliente de base: dibujá encima lo que instalaste.");
      } catch (err) { carga.remove(); showToast("No se pudo usar el plano: " + err.message); }
    }
  });
});
document.getElementById("instPlanoFotoBtn").addEventListener("click", () => { if (instalacionActivaId) document.getElementById("instPlanoArchivoInput").click(); });
// Sin señal, la foto del plano queda guardada en el celular y se sube sola
// cuando vuelve la señal (antes de cerrar la instalación se reintenta).
const PLANOS_PENDIENTES = "planos_instalacion_pendientes";
function planosPendientesLeer() { try { const l = JSON.parse(localStorage.getItem(PLANOS_PENDIENTES) || "[]"); return Array.isArray(l) ? l : []; } catch (e) { return []; } }
function planosPendientesGuardar(lista) { localStorage.setItem(PLANOS_PENDIENTES, JSON.stringify(lista)); }
function planosPendientesDe(inst) { return planosPendientesLeer().filter((p) => String(p.instalacion) === String(inst)); }
function planosPendientesQuitar(uid) { try { planosPendientesGuardar(planosPendientesLeer().filter((p) => p.uid !== uid)); } catch (e) { /* nada */ } }
// Sube un plano (imágenes ya achicadas) como croquis de la instalación.
async function instPlanoSubirImagenes(p) {
  const fondos = await croquisSubirPlanosBase(p.imagenes, SERVICIOS_API_TOKEN);
  const paginas = croquisPaginasDesdeFondos(fondos);
  if (paginas.length === 1) paginas[0].nombre = "Foto del plano";
  const r = await fetch("/api/datos?coleccion=croquis", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN },
    body: JSON.stringify({ accion: "guardar", instalacion: String(p.instalacion), titulo: p.titulo || "Foto del plano", cliente: p.cliente || "", numero_cliente: p.numero_cliente || "", direccion: p.direccion || "", dibujo: { v: 2, elementos: [], paginas, fondo: fondos[0] } }),
  });
  const d = await r.json().catch(() => ({}));
  if (r.status === 403 && d.cerrado) { const e = new Error(d.error); e.definitivo = true; throw e; }
  if (!r.ok || !d.ok) throw new Error(d.error || "HTTP " + r.status);
  return d;
}
let planosPendientesSubiendo = null;
function planosPendientesSubir() {
  if (planosPendientesSubiendo) return planosPendientesSubiendo;
  planosPendientesSubiendo = (async () => {
    let subidos = 0;
    for (const p of planosPendientesLeer()) {
      try { await instPlanoSubirImagenes(p); planosPendientesQuitar(p.uid); subidos++; }
      catch (err) { if (err.definitivo) { planosPendientesQuitar(p.uid); showToast("Un plano guardado sin señal no se pudo subir: " + err.message); } }
    }
    if (subidos) { showToast(subidos === 1 ? "Se subió el plano que había quedado sin señal." : `Se subieron ${subidos} planos que habían quedado sin señal.`); if (instalacionActivaId) instPlanoCargar(); }
    return subidos;
  })().finally(() => { planosPendientesSubiendo = null; });
  return planosPendientesSubiendo;
}
window.addEventListener("online", () => { if (planosPendientesLeer().length) planosPendientesSubir(); });
setTimeout(() => { try { if (planosPendientesLeer().length && navigator.onLine !== false && SERVICIOS_API_TOKEN) planosPendientesSubir(); } catch (e) { /* nada */ } }, 4000);
function esErrorDeRed(err) { return navigator.onLine === false || (err && (err.name === "TypeError" || /Failed to fetch|NetworkError|Load failed|network/i.test(err.message || ""))); }
document.getElementById("instPlanoArchivoInput").addEventListener("change", async (e) => {
  const archivo = e.target.files && e.target.files[0];
  e.target.value = "";
  if (!archivo || !instalacionActivaId) return;
  const dat = instalacionActivaDatos || {};
  instPlanoEstado.textContent = "Preparando el plano...";
  let pendiente = null;
  try {
    const imagenes = (await croquisArchivoAImagenes(archivo, 2000, CROQUIS_MAX_HOJAS)).map(({ base64, w, h }) => ({ base64, w, h }));
    pendiente = { uid: cqId(), instalacion: String(instalacionActivaId), titulo: "Foto del plano", cliente: dat.cliente || instalacionClienteInput.value.trim(), numero_cliente: dat.numero_cliente || "", direccion: dat.direccion || "", imagenes, creado: new Date().toISOString() };
    instPlanoEstado.textContent = "Subiendo el plano...";
    await instPlanoSubirImagenes(pendiente);
    instPlanoEstado.textContent = "";
    showToast(imagenes.length > 1 ? `Plano guardado en la instalación (${imagenes.length} hojas).` : "Plano guardado en la instalación. Si querés, abrilo para marcar encima lo instalado.");
    instPlanoCargar();
  } catch (err) {
    if (pendiente && esErrorDeRed(err)) {
      try {
        planosPendientesGuardar([...planosPendientesLeer(), pendiente]);
        instPlanoEstado.textContent = "";
        showToast("Sin señal: el plano quedó guardado en el celular y se sube solo cuando vuelva la señal.");
        instPlanoRender();
      } catch (e2) { instPlanoEstado.textContent = "Sin señal y no hay lugar en el celular para guardarlo. Probá de nuevo con señal."; }
      return;
    }
    instPlanoEstado.textContent = "No se pudo subir: " + err.message;
  }
});

// PDF de cada plano de la instalación, para adjuntarlo al mail de cierre.
function bytesABase64(bytes) { let bin = ""; for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000)); return btoa(bin); }
async function instPlanosPdf(planos) {
  const out = [];
  for (const c of planos.slice(0, 6)) {
    try {
      const d = await instPlanoTraer(c.id);
      let bytes = await croquisPdf(d, { ancho: 1800 });
      if (bytes.length > 3200000) bytes = await croquisPdf(d, { ancho: 1200 });
      const r = await fetch("/api/foto", { method: "POST", headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN }, body: JSON.stringify({ base64: bytesABase64(bytes), tipo: "pdf" }) });
      const res = await r.json().catch(() => ({}));
      if (r.ok && res.id) out.push({ id: res.id, nombre: (c.titulo || "Plano") + (planos.length > 1 ? " " + (out.length + 1) : "") });
      // Y a la carpeta de Planos de la oficina (PDF + SVG para Visio).
      try { await croquisMandarACarpetaVisio({ ...d, cerrado_en: new Date().toISOString() }, SERVICIOS_API_TOKEN, bytes); }
      catch (errVisio) { console.error("[plano] no se pudo mandar a la carpeta de Visio", errVisio); try { registrarErrorApp("Plano a carpeta Visio: " + errVisio.message, "croquis"); } catch (e) { /* nada */ } }
    } catch (err) { console.error("[plano] no se pudo armar el PDF", err); }
  }
  return out;
}

