// ---------- PDF ----------
function peCargarPdfLib() {
  if (window.PDFLib) return Promise.resolve(window.PDFLib);
  return new Promise((ok, mal) => {
    const sc = document.createElement("script");
    sc.src = "vendor/pdf-lib.min.js";
    sc.onload = () => (window.PDFLib ? ok(window.PDFLib) : mal(new Error("No cargó el generador de PDF")));
    sc.onerror = () => mal(new Error("No se pudo cargar el generador de PDF (¿sin señal?)"));
    document.head.appendChild(sc);
  });
}
// Las letras estándar del PDF no tienen algunos símbolos: se reemplazan.
function peTextoPdf(s) {
  return String(s == null ? "" : s)
    .replace(/[‘’‚]/g, "'").replace(/„/g, '"').replace(/[–—]/g, "-").replace(/…/g, "...")
    .replace(/[\t\r]/g, " ")
    .replace(/[^\n\x20-\x7E\xA0-\xFF“”]/g, "");
}
async function peGenerarPdf(datos) {
  const { PDFDocument, StandardFonts, rgb } = await peCargarPdfLib();
  const doc = await PDFDocument.create();
  doc.setTitle(`Presupuesto ${datos.numero}`);
  doc.setAuthor("SAT - Servicio Técnico");
  const fN = await doc.embedFont(StandardFonts.Helvetica);
  const fB = await doc.embedFont(StandardFonts.HelveticaBold);
  const bytes = async (url) => new Uint8Array(await (await fetch(url)).arrayBuffer());
  let logoSat = null, logoCemara = null;
  try { logoSat = await doc.embedJpg(await bytes("assets/presupuesto/logo-sat.jpg")); } catch (e) { /* sin logo */ }
  try { logoCemara = await doc.embedJpg(await bytes("assets/presupuesto/logo-cemara.jpg")); } catch (e) { /* sin logo */ }
  // Según los artículos: equipos AJAX y comunicador CityMesh (EXODUS).
  const tieneArticulo = (re) => datos.items.some((it) => re.test(normalizeText(`${it.d || ""} ${it.c || ""}`)));
  const hayAjax = tieneArticulo(/\bajax\b/);
  const hayCityMesh = tieneArticulo(/city\s*-?\s*mesh/);
  // El logo de AJAX va en el encabezado solo si hay artículos AJAX.
  let logoAjax = null;
  if (hayAjax) { try { logoAjax = await doc.embedPng(await bytes("assets/presupuesto/logo-ajax.png")); } catch (e) { /* sin logo */ } }
  const A4 = [595.28, 841.89];
  const X = 86, ANCHO = A4[0] - X - 70, ABAJO = 70;
  const negro = rgb(0, 0, 0), gris = rgb(0.85, 0.85, 0.85), grisOsc = rgb(0.35, 0.35, 0.35), amarillo = rgb(1, 0.753, 0.2);
  let pag = doc.addPage(A4);
  let y = A4[1] - 34;
  const nuevaPagina = () => { pag = doc.addPage(A4); y = A4[1] - 60; };
  const asegurar = (alto) => { if (y - alto < ABAJO) nuevaPagina(); };
  const texto = (t, x, tam, fuente, color) => pag.drawText(peTextoPdf(t), { x, y, size: tam, font: fuente, color: color || negro });
  const ancho = (t, tam, fuente) => fuente.widthOfTextAtSize(peTextoPdf(t), tam);
  const subrayar = (x, w, tam) => pag.drawLine({ start: { x, y: y - 1.6 }, end: { x: x + w, y: y - 1.6 }, thickness: tam > 11 ? 0.9 : 0.7, color: negro });
  const partir = (t, tam, fuente, w) => {
    const out = [];
    peTextoPdf(t).split("\n").forEach((par) => {
      let linea = "";
      par.split(/\s+/).filter(Boolean).forEach((pal) => {
        const prueba = linea ? linea + " " + pal : pal;
        if (fuente.widthOfTextAtSize(prueba, tam) > w && linea) { out.push(linea); linea = pal; } else linea = prueba;
      });
      if (linea) out.push(linea);
    });
    return out.length ? out : [""];
  };
  // Encabezado: logos
  if (logoSat) { const h = 66, w = h * logoSat.width / logoSat.height; pag.drawImage(logoSat, { x: 38, y: y - h, width: w, height: h }); }
  if (logoCemara) { const h = 54, w = h * logoCemara.width / logoCemara.height; pag.drawImage(logoCemara, { x: A4[0] - 38 - w, y: y - h - 4, width: w, height: h }); }
  if (logoAjax) { const h = 38, w = h * logoAjax.width / logoAjax.height; pag.drawImage(logoAjax, { x: (A4[0] - w) / 2, y: y - 33 - h / 2, width: w, height: h }); }
  y -= 96;
  // Título: "Presupuesto" ... “Título”
  texto("Presupuesto", X, 12.5, fB); subrayar(X, ancho("Presupuesto", 12.5, fB), 12.5);
  const tit = datos.titulo ? `“${datos.titulo.replace(/^["“]+|["”]+$/g, "")}”` : "";
  if (tit) { const w = ancho(tit, 12.5, fB); texto(tit, X + ANCHO - w, 12.5, fB); }
  y -= 4;
  pag.drawLine({ start: { x: X, y }, end: { x: X + ANCHO, y }, thickness: 0.9, color: negro });
  // Leyenda PRESUPUESTO EXPRESS
  y -= 22;
  pag.drawRectangle({ x: X, y: y - 5, width: ANCHO, height: 19, color: amarillo });
  const ley = "PRESUPUESTO EXPRESS";
  texto(ley, X + (ANCHO - ancho(ley, 11, fB)) / 2, 11, fB);
  y -= 28;
  // Datos
  const filaDato = (etiqueta, valor) => {
    texto(etiqueta + " ", X, 10.5, fN);
    const w = ancho(etiqueta + " ", 10.5, fN);
    partir(valor || "", 10.5, fB, ANCHO - w).forEach((l, i) => { if (i) { y -= 13.5; } texto(l, X + w, 10.5, fB); });
    y -= 13.5;
  };
  filaDato("Fecha:", datos.fecha);
  filaDato("N° Presupuesto:", datos.numero);
  filaDato("N° Cliente:", datos.cliente.numero_cliente);
  filaDato("Nombre:", datos.cliente.nombre);
  filaDato("Dirección:", datos.cliente.direccion);
  filaDato("Teléfono:", datos.cliente.telefono);
  filaDato("Razón Social:", datos.cliente.razon_social);
  filaDato("CUIT:", datos.cliente.cuit);
  if (PE_TIPOS[datos.tipo]) filaDato("Tipo de trabajo:", PE_TIPOS[datos.tipo].nombre);
  // Materiales
  y -= 18;
  if (datos.items.length) {
    asegurar(40);
    texto("Materiales:", X, 10.5, fB); subrayar(X, ancho("Materiales:", 10.5, fB), 10.5);
    y -= 24;
    // Fotos de los artículos que la oficina cargó (como en los presupuestos de siempre).
    const fotos = peLista.fotos || {};
    const imagenes = await Promise.all(datos.items.map(async (it) => {
      const id = !it.manual && fotos[(it.c && String(it.c).trim()) || it.d];
      if (!id) return null;
      try {
        const r = await fetch(`/api/foto?id=${encodeURIComponent(id)}`);
        if (!r.ok) return null;
        const b = new Uint8Array(await r.arrayBuffer());
        return b[0] === 0x89 ? await doc.embedPng(b) : await doc.embedJpg(b);
      } catch (e) { return null; }
    }));
    datos.items.forEach((it, i) => {
      const lineas = partir(it.d, 10, fN, ANCHO - 30);
      const img = imagenes[i];
      const altoImg = img ? 54 : 0;
      asegurar(lineas.length * 12.5 + 10 + (img ? altoImg + 8 : 0));
      const cant = String(it.cant);
      texto(cant, X + 18 - ancho(cant, 10, fN), 10, fN);
      lineas.forEach((l) => { texto(l, X + 28, 10, fN); y -= 12.5; });
      if (img) {
        const w = Math.min(110, altoImg * img.width / img.height);
        const h = w * img.height / img.width;
        pag.drawImage(img, { x: X + 28, y: y - h + 4, width: w, height: h });
        y -= h + 4;
      }
      y -= 9;
    });
  }
  // Totales (recuadro gris como el modelo)
  y -= 6;
  const lineasTot = [["Total Materiales:", pePesos(datos.total_materiales) + ".-"], ["Total Mano de Obra:", pePesos(datos.mano_obra) + ".-" + (datos.mo_iva ? " + IVA" : "")]];
  if (datos.ajuste_linea) lineasTot.push(["Ajuste por redondeo:", (datos.ajuste_linea > 0 ? "+" : "-") + pePesos(Math.abs(datos.ajuste_linea)) + ".-"]);
  lineasTot.push(["TOTAL:", pePesos(datos.total) + ".-" + (datos.mo_iva ? " (+ IVA de la mano de obra)" : "")]);
  const altoCaja = 28 + lineasTot.length * 21;
  const anchoCajaTot = Math.max(262, ...lineasTot.map(([et, val], i) => { const tam = i === lineasTot.length - 1 ? 11.5 : 10.5; return ancho(et, tam, fB) + ancho(val, tam, fB) + 24; }));
  const conAbono = datos.abono > 0 && PE_TIPOS[datos.tipo] && PE_TIPOS[datos.tipo].abono;
  asegurar(altoCaja + 175 + (conAbono ? 52 : 0)); // totales + abono + pago + garantía + validez + pie: todo junto en la misma hoja
  pag.drawRectangle({ x: X - 8, y: y - altoCaja + 12, width: Math.min(ANCHO + 16, anchoCajaTot), height: altoCaja, color: gris, borderColor: grisOsc, borderWidth: 0.8 });
  lineasTot.forEach(([et, val], i) => {
    const ultima = i === lineasTot.length - 1;
    const tam = ultima ? 11.5 : 10.5;
    texto(et, X, tam, fB); subrayar(X, ancho(et, tam, fB), tam);
    texto(val, X + ancho(et, tam, fB) + 6, tam, fB);
    y -= i === lineasTot.length - 2 ? 22 : 21;
  });
  y -= 14;
  if (conAbono) {
    // Abono mensual: aparte del total, en su propio recuadro.
    const et = PE_TIPOS[datos.tipo].abono + ":", val = pePesos(datos.abono) + ".-" + (datos.abono_iva ? " + IVA" : "") + " por mes";
    const anchoCaja = Math.max(262, ancho(et, 10.5, fB) + ancho(val, 10.5, fB) + 30);
    pag.drawRectangle({ x: X - 8, y: y - 9, width: anchoCaja, height: 26, color: amarillo, borderColor: grisOsc, borderWidth: 0.8 });
    texto(et, X, 10.5, fB); subrayar(X, ancho(et, 10.5, fB), 10.5);
    texto(val, X + ancho(et, 10.5, fB) + 6, 10.5, fB);
    y -= 38;
  }
  const pie = (et, val) => { texto(et, X, 10.5, fB); subrayar(X, ancho(et, 10.5, fB), 10.5); texto(val, X + ancho(et, 10.5, fB) + 6, 10.5, fB); y -= 21; };
  pie("Forma de Pago:", datos.forma_pago);
  pie("Garantía:", "12 meses");
  pie("Validez:", "3 días");
  const fin = datos.mo_iva || (conAbono && datos.abono_iva) ? "PRECIOS CON IVA INCLUIDO, SALVO DONDE DICE + IVA" : "PRECIO FINAL - IVA INCLUIDO";
  texto(fin, X + (ANCHO - ancho(fin, 10.5, fB)) / 2, 10.5, fB);
  y -= 14;
  // Sistema monitoreado: lo que incluye el servicio.
  if (datos.tipo === "monitoreado") {
    const servicios = PE_SERVICIOS_MONITOREO.map((l) => partir(l, 9.5, fN, ANCHO - 20));
    asegurar(40 + servicios.reduce((n, ls) => n + ls.length * 12.5 + 2, 0));
    y -= 14;
    const tit = "SERVICIOS INCLUIDOS CON MONITOREO";
    texto(tit, X, 10.5, fB); subrayar(X, ancho(tit, 10.5, fB), 10.5);
    y -= 18;
    servicios.forEach((ls) => {
      texto("§", X + 6, 9.5, fB);
      ls.forEach((l) => { texto(l, X + 20, 9.5, fN); y -= 12.5; });
      y -= 2;
    });
    y -= 4;
  }
  // Equipos AJAX: se ofrecen los demás detectores de la línea.
  if (hayAjax) {
    const nota = partir("Consultar por detectores de humo, Monóxido, vibración, inundación, pulsadores de asalto, etc", 10, fB, ANCHO);
    asegurar(nota.length * 13 + 26);
    y -= 10;
    nota.forEach((l) => { texto(l, X, 10, fB); y -= 13; });
    y -= 2;
    pag.drawLine({ start: { x: X, y }, end: { x: X + ANCHO, y }, thickness: 0.8, color: negro, dashArray: [3, 2] });
    y -= 8;
  }
  asegurar(80);
  pag.drawLine({ start: { x: X + 10, y }, end: { x: X + ANCHO - 10, y }, thickness: 0.6, color: negro });
  y -= 22;
  ["SAT - de Alfredo Thiesing", "Bv. Avellaneda 408 - Tel/Fax: 4377578 - WhatsApp: 341-3782085 - e-mail:", "thiesing@sat365.com.ar", "2000 Rosario - Santa Fe - Argentina"].forEach((l) => {
    texto(l, X + (ANCHO - ancho(l, 10, fB)) / 2, 10, fB); y -= 13;
  });
  // Monitoreado con CityMesh: va el folleto de EXODUS al final (en una hoja propia si no entra).
  if (datos.tipo === "monitoreado" && hayCityMesh) {
    try {
      const folleto = await doc.embedJpg(await bytes("assets/presupuesto/exodus-citymesh.jpg"));
      const maxW = A4[0] - 2 * 50;
      let w = maxW, h = w * folleto.height / folleto.width;
      y -= 16;
      if (y - h < 40) { nuevaPagina(); y = A4[1] - 40; const maxH = A4[1] - 80; if (h > maxH) { h = maxH; w = h * folleto.width / folleto.height; } }
      pag.drawImage(folleto, { x: (A4[0] - w) / 2, y: y - h, width: w, height: h });
    } catch (e) { /* sin folleto */ }
  }
  return await doc.save();
}

pe("peGenerarBtn").addEventListener("click", async () => {
  const c = peEstado.cliente;
  if (!c.nombre.trim()) {
    if (peEstado.modo === "listado" && !peEstado.clienteElegido) { showToast("Elegí el cliente del listado, o tocá «Cliente nuevo»."); pe("peClienteBuscar").focus(); return; }
    pe("peNombre").classList.add("campo-falta"); showToast("Falta el nombre del cliente."); pe("peNombre").focus(); return;
  }
  if (!PE_TIPOS[peEstado.tipo]) { pe("peTipos").classList.add("campo-falta"); showToast("Elegí si es una ampliación, un sistema monitoreado o con automonitoreo."); pe("peTipos").scrollIntoView({ block: "center", behavior: "smooth" }); return; }
  if (peLlevaAbono() && !(peNumero(peEstado.abono) > 0)) { pe("peAbono").classList.add("campo-falta"); showToast("Poné el costo mensual del abono."); pe("peAbono").focus(); return; }
  if (String(peEstado.mano_obra).trim() === "" || isNaN(peNumero(peEstado.mano_obra))) { pe("peManoObra").classList.add("campo-falta"); showToast("Poné el costo de la mano de obra (si no lleva, poné 0)."); pe("peManoObra").focus(); return; }
  const t = peCalcular();
  const abono = peLlevaAbono() ? Math.round(peNumero(peEstado.abono)) : null;
  if (t.faltaCotiz) { showToast("Hay artículos en dólares sin cotización cargada."); return; }
  if (!peEstado.items.length && !t.mano_obra) { showToast("Agregá algún material o la mano de obra."); return; }
  const btn = pe("peGenerarBtn");
  btn.disabled = true;
  const textoBtn = btn.textContent;
  btn.textContent = "Armando el presupuesto...";
  try {
    // El número se reserva en el servidor (E-0001, E-0002...).
    const r = await fetch("/api/datos?coleccion=presupuestos_express", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN },
      body: JSON.stringify({ accion: peEstado.revisionDe ? "revision" : "nuevo", base: peEstado.revisionDe || undefined, cliente: c.nombre, numero_cliente: c.numero_cliente, titulo: peEstado.titulo, total_materiales: t.materiales, mano_obra: t.mano_obra, total: t.total, forma_pago: peEstado.forma_pago, tipo: peEstado.tipo, abono, mo_iva: !!peEstado.mo_iva, abono_iva: !!(abono && peEstado.abono_iva), ajuste: t.ajuste || 0, cotizacion_usd: t.hayUsd ? peLista.cotizacion_usd : null, articulos: peEstado.items.length }),
    });
    const d = await r.json().catch(() => ({}));
    if (!r.ok || !d.numero) throw new Error(d.error || "No se pudo sacar el número de presupuesto (¿hay señal?)");
    const hoy = new Date();
    const datos = {
      numero: d.numero, fecha: `${String(hoy.getDate()).padStart(2, "0")}-${String(hoy.getMonth() + 1).padStart(2, "0")}-${hoy.getFullYear()}`,
      titulo: peEstado.titulo.trim(), cliente: { ...c }, items: peEstado.items.map((it) => ({ c: it.c || "", d: it.d, cant: it.cant, manual: !!it.manual })),
      vence: (() => { const v = new Date(hoy.getTime() + 3 * 864e5); return `${String(v.getDate()).padStart(2, "0")}-${String(v.getMonth() + 1).padStart(2, "0")}-${v.getFullYear()}`; })(),
      total_materiales: t.materiales, mano_obra: t.mano_obra, total: t.total, forma_pago: peEstado.forma_pago,
      tipo: peEstado.tipo, abono, mo_iva: !!peEstado.mo_iva, abono_iva: !!peEstado.abono_iva,
      ajuste_linea: t.ajuste && !t.ajusteEnMO ? t.ajuste : 0,
    };
    const pdf = await peGenerarPdf(datos);
    const nombreArchivo = `Presupuesto_${d.numero}_${(c.nombre || "cliente").replace(/[^\wÁÉÍÓÚÑáéíóúñ]+/g, "_").slice(0, 40)}.pdf`;
    peUltimoPdf = { blob: new Blob([pdf], { type: "application/pdf" }), nombre: nombreArchivo, numero: d.numero, total: t.total, cliente: c.nombre, telefono: c.telefono, titulo: peEstado.titulo.trim(), vence: datos.vence, link: "", abono, tipo: peEstado.tipo, mo_iva: !!peEstado.mo_iva, abono_iva: !!peEstado.abono_iva };
    peGuardarHecho(d.numero, t.total);
    peEstado.revisionDe = "";
    peGuardarBorrador();
    peRenderRevision();
    peRenderHechos();
    peMostrarResultado();
    peUltimoPdf.copia = peGuardarCopia(pdf, d.numero).then((id) => { if (id && peUltimoPdf && peUltimoPdf.numero === d.numero) peUltimoPdf.link = `${location.origin}/api/foto?id=${id}&tipo=pdf`; return id; });
    await peCompartir(true);
  } catch (err) {
    showToast(err.message || "No se pudo generar el presupuesto.");
  } finally {
    btn.disabled = false;
    btn.textContent = textoBtn;
  }
});
function peMostrarResultado() {
  let box = pe("peResultado");
  if (!box) {
    box = document.createElement("div");
    box.id = "peResultado";
    box.className = "pe-resultado";
    pe("peGenerarBtn").insertAdjacentElement("afterend", box);
  }
  box.innerHTML = `<b>Presupuesto ${escapeHtml(peUltimoPdf.numero)} listo</b><span>${escapeHtml(peUltimoPdf.cliente)} · ${pePesos(peUltimoPdf.total)}</span>
    <div class="pe-resultado-btns"><button type="button" class="btn btn-primary btn-small" id="peWhatsappClienteBtn">Enviar al WhatsApp del cliente</button><button type="button" class="btn btn-secondary btn-small" id="peCompartirBtn">Compartir el PDF</button><button type="button" class="btn btn-secondary btn-small" id="peVerBtn">Ver / descargar</button></div>`;
  pe("peCompartirBtn").addEventListener("click", () => peCompartir(false));
  pe("peWhatsappClienteBtn").addEventListener("click", peEnviarWhatsappCliente);
  pe("peVerBtn").addEventListener("click", () => {
    const url = URL.createObjectURL(peUltimoPdf.blob);
    const a = document.createElement("a");
    a.href = url; a.download = peUltimoPdf.nombre; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  });
}
async function peCompartir(automatico) {
  if (!peUltimoPdf) return;
  const archivo = new File([peUltimoPdf.blob], peUltimoPdf.nombre, { type: "application/pdf" });
  const texto = `Presupuesto ${peUltimoPdf.numero} - SAT Servicio Técnico`;
  try {
    if (navigator.canShare && navigator.canShare({ files: [archivo] })) { await navigator.share({ files: [archivo], title: texto, text: texto }); return; }
  } catch (e) {
    if (e && e.name === "AbortError") return;
    if (automatico) return; // sin permiso para compartir solo: queda el botón «Compartir»
  }
  if (!automatico) pe("peVerBtn").click();
}
// Copia del PDF en el servidor (para que la oficina lo tenga); si falla no pasa nada.
async function peGuardarCopia(pdf, numero) {
  try {
    let bin = "";
    const u8 = new Uint8Array(pdf);
    for (let i = 0; i < u8.length; i += 0x8000) bin += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000));
    const r = await fetch("/api/foto", { method: "POST", headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN }, body: JSON.stringify({ base64: btoa(bin), tipo: "pdf" }) });
    const d = await r.json();
    if (!r.ok || !d.id) return "";
    fetch("/api/datos?coleccion=presupuestos_express", { method: "POST", headers: { "Content-Type": "application/json", Authorization: "Bearer " + SERVICIOS_API_TOKEN }, body: JSON.stringify({ accion: "adjuntar_pdf", numero, pdf_id: d.id }) }).catch(() => {});
    return d.id;
  } catch (e) { return ""; }
}
// Celular para WhatsApp: con código de área (Rosario 341 si viene de 7 dígitos), sin 0 ni 15.
function peCelularWhatsapp(tel) {
  let n = String(tel || "").replace(/\D/g, "");
  if (!n) return "";
  if (n.startsWith("54")) n = n.slice(2);
  if (n.startsWith("9")) n = n.slice(1);
  n = n.replace(/^0/, "");
  if (n.length === 7) n = "341" + n;
  const m = n.match(/^(\d{2,4})15(\d{6,8})$/);
  if (m && (m[1] + m[2]).length === 10) n = m[1] + m[2];
  return n.length === 10 ? "549" + n : "";
}
// Abre el chat del cliente con un mensaje listo y el link al PDF.
async function peEnviarWhatsappCliente() {
  if (!peUltimoPdf) return;
  const sugerido = peCelularWhatsapp(peUltimoPdf.telefono);
  const escrito = await pedirTextoApp("Celular de WhatsApp del cliente (con código de área, ej. 341 555 1234):", sugerido ? sugerido.replace(/^549/, "") : "");
  if (escrito === null) return;
  const numero = peCelularWhatsapp(escrito);
  if (!numero) { showToast("Ese número no parece un celular con código de área (ej. 341 555 1234)."); return; }
  const btn = pe("peWhatsappClienteBtn");
  if (!peUltimoPdf.link && peUltimoPdf.copia) { btn.textContent = "Preparando el link..."; try { await peUltimoPdf.copia; } catch (e) { /* nada */ } btn.textContent = "Enviar al WhatsApp del cliente"; }
  const nombre = String(peUltimoPdf.cliente || "").split(/[-,]/)[0].trim();
  const texto = `Hola${nombre ? " " + nombre : ""}! Te enviamos el presupuesto ${peUltimoPdf.numero} de SAT${peUltimoPdf.titulo ? ` (${peUltimoPdf.titulo})` : ""}.\nTotal: ${pePesos(peUltimoPdf.total)} ${peUltimoPdf.mo_iva ? "(la mano de obra es + IVA)" : "(precio final, IVA incluido)"}.${peUltimoPdf.abono > 0 && PE_TIPOS[peUltimoPdf.tipo] ? `\n${PE_TIPOS[peUltimoPdf.tipo].abono}: ${pePesos(peUltimoPdf.abono)}${peUltimoPdf.abono_iva ? " + IVA" : ""} por mes.` : ""} Válido hasta el ${peUltimoPdf.vence}.` + (peUltimoPdf.link ? `\nPodés verlo acá: ${peUltimoPdf.link}` : "\nTe paso el PDF a continuación.") + "\nCualquier consulta, a disposición.";
  window.open(`https://wa.me/${numero}?text=${encodeURIComponent(texto)}`, "_blank", "noopener");
  if (!peUltimoPdf.link) showToast("No se pudo subir el PDF: mandalo con «Compartir el PDF».");
}

// ============================================================
// CROQUIS — editor de bocetos de planos desde el celular.
// Dibujo en SVG sobre una grilla: habitaciones (rectángulos), paredes
// (líneas), cableado (curva a mano alzada), textos y los equipos
// (central, teclado, magnético, infrarrojo, infrarrojo exterior) que se
// pueden mover, rotar y agrandar. Zoom y desplazamiento con dos dedos.
// Se guarda en el servidor, ligado a un cliente, y se descarga en PDF,
// PNG o SVG (el SVG se abre y edita en Visio).
// ============================================================
const CQ_BORRADOR = "croquis_borrador";
const cq = {
  id: "", titulo: "", cliente: "", numero_cliente: "", direccion: "", autor: "",
  elementos: [], sel: null, herr: "mover", simboloElegido: "",
  vista: { x: -40, y: -40, s: 1 }, pasado: [], futuro: [], cambios: false,
  paginas: [], pagina: 0, multi: [], modoMulti: false, cadena: null,
};
