const ayudaBtn = (clave) => `<button type="button" class="ayuda-btn" data-ayuda="${clave}" aria-label="Ayuda: ${escapeHtml((AYUDAS_STOCK[clave] || {}).titulo || "")}" aria-expanded="false">?</button>`;
const ayudaPopApp = document.createElement("div");
ayudaPopApp.className = "ayuda-pop hidden";
ayudaPopApp.setAttribute("role", "dialog");
document.body.appendChild(ayudaPopApp);
let ayudaAppAbierta = null, ayudaAppFijada = false, ayudaAppTimer = null;
function mostrarAyudaApp(boton, fijar) {
  const a = AYUDAS_STOCK[boton.dataset.ayuda];
  if (!a) return;
  clearTimeout(ayudaAppTimer);
  if (ayudaAppAbierta && ayudaAppAbierta !== boton) ayudaAppAbierta.setAttribute("aria-expanded", "false");
  ayudaAppAbierta = boton; ayudaAppFijada = !!fijar;
  ayudaPopApp.innerHTML = `<div class="ayuda-pop-cab"><b>${escapeHtml(a.titulo)}</b><button type="button" class="ayuda-pop-cerrar" aria-label="Cerrar">${stkIco("x")}</button></div>
    ${a.gif ? `<img src="${a.gif}" alt="Ejemplo animado: ${escapeHtml(a.titulo)}" class="ayuda-pop-gif">` : ""}
    <ul>${a.texto.map((x) => `<li>${escapeHtml(x)}</li>`).join("")}</ul>`;
  ayudaPopApp.querySelector(".ayuda-pop-cerrar").addEventListener("click", ocultarAyudaApp);
  ayudaPopApp.classList.remove("hidden");
  const gif = ayudaPopApp.querySelector(".ayuda-pop-gif");
  if (gif && !gif.complete) gif.addEventListener("load", () => { if (ayudaAppAbierta === boton) ubicarAyudaApp(boton); }, { once: true });
  ubicarAyudaApp(boton);
  boton.setAttribute("aria-expanded", "true");
}
// En el celular sale como una hoja desde abajo; en pantallas grandes, al lado del «?».
function ubicarAyudaApp(boton) {
  const p = ayudaPopApp;
  if (window.innerWidth < 700) { p.classList.add("hoja"); p.style.left = p.style.top = p.style.width = ""; return; }
  p.classList.remove("hoja");
  const r = boton.getBoundingClientRect(), ancho = Math.min(460, window.innerWidth - 24);
  p.style.width = ancho + "px";
  p.style.left = Math.max(12, Math.min(r.left + r.width / 2 - ancho / 2, window.innerWidth - ancho - 12)) + "px";
  // Nunca tapa su propio «?»: va abajo o arriba (donde haya más lugar) y, si no entra, se achica con scroll.
  p.style.maxHeight = ""; p.style.overflowY = "";
  const alto = p.offsetHeight || 420, abajo = window.innerHeight - r.bottom - 16, arriba = r.top - 16;
  if (alto <= abajo) p.style.top = r.bottom + 8 + "px";
  else if (alto <= arriba) p.style.top = r.top - alto - 8 + "px";
  else if (abajo >= arriba) { p.style.maxHeight = Math.max(120, abajo) + "px"; p.style.overflowY = "auto"; p.style.top = r.bottom + 8 + "px"; }
  else { const h = Math.max(120, arriba); p.style.maxHeight = h + "px"; p.style.overflowY = "auto"; p.style.top = Math.max(8, r.top - h - 8) + "px"; }
}
function ocultarAyudaApp() {
  ayudaPopApp.classList.add("hidden");
  if (ayudaAppAbierta) ayudaAppAbierta.setAttribute("aria-expanded", "false");
  ayudaAppAbierta = null; ayudaAppFijada = false;
}
// Delegado: sirve también para los «?» que se dibujan después (listas que cambian).
document.addEventListener("pointerover", (e) => {
  const b = e.target.closest && e.target.closest(".ayuda-btn[data-ayuda]");
  // (en pantallas angostas la ayuda es una hoja que tapa todo: ahí solo se abre al tocar el «?»)
  if (b && e.pointerType === "mouse" && window.innerWidth >= 700 && !ayudaAppFijada && AYUDAS_STOCK[b.dataset.ayuda]) mostrarAyudaApp(b, false);
});
document.addEventListener("pointerout", (e) => {
  const b = e.target.closest && e.target.closest(".ayuda-btn[data-ayuda]");
  if (b && e.pointerType === "mouse" && !ayudaAppFijada && !(e.relatedTarget && ayudaPopApp.contains(e.relatedTarget))) ayudaAppTimer = setTimeout(ocultarAyudaApp, 250);
});
document.addEventListener("click", (e) => {
  const b = e.target.closest && e.target.closest(".ayuda-btn[data-ayuda]");
  if (b && AYUDAS_STOCK[b.dataset.ayuda]) {
    e.preventDefault(); e.stopPropagation(); // dentro de un <summary> no abre ni cierra el desplegable
    if (ayudaAppAbierta === b && ayudaAppFijada) ocultarAyudaApp(); else mostrarAyudaApp(b, true);
    return;
  }
  if (ayudaAppAbierta && !ayudaPopApp.contains(e.target)) ocultarAyudaApp();
}, true);
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && ayudaAppAbierta) ocultarAyudaApp(); });
ayudaPopApp.addEventListener("mouseenter", () => clearTimeout(ayudaAppTimer));
ayudaPopApp.addEventListener("mouseleave", () => { if (!ayudaAppFijada) ayudaAppTimer = setTimeout(ocultarAyudaApp, 250); });
// Los «?» fijos de las pantallas (los de las listas se dibujan con ayudaBtn()).
[["#screen-deposito .stk-unico .stk-ayuda", "dep_escanear"], ['label[for="depDestTipo"]', "dep_entregar"], ['label[for="depRecibirTipo"]', "dep_alta"],
  ['#screen-deposito [data-dep="inventario"] > .stk-ayuda', "dep_inventario"], ["#depConsultarAyuda", "dep_consultar"],
  ["#screen-mistock .stk-mi-codigo .stk-ayuda", "mi_codigo"], ["#miStockPedirCaja summary", "mi_pedir"], ["#miCamCaja summary", "mi_camioneta"], ["#miStockDevolverCaja > .stk-h", "mi_devolver"],
  ['label[for="f_materiales"]', "parte_stock"]].forEach(([sel, clave]) => { const el = document.querySelector(sel); if (el && !el.querySelector(".ayuda-btn")) el.insertAdjacentHTML("beforeend", " " + ayudaBtn(clave)); });

// ---------- Mi stock ----------
let miStock = null;
let miStockAvisoAt = 0;
const miStockCatalogo = () => ({ articulos: (miStock && miStock.articulos) || {} });
const miStockSaldos = () => {
  if (!miStock) return { ubic: {}, unidades: {} };
  const u = {};
  (miStock.unidades || []).forEach((x) => { u[x.tracking] = { c: x.c, u: `tec:${miStock.nombre}` }; });
  return { ubic: { [`tec:${miStock.nombre}`]: miStock.tiene || {} }, unidades: u };
};
const miStockCanasta = crearCanastaStock({
  cont: document.getElementById("miStockCanasta"),
  catalogo: miStockCatalogo, saldos: miStockSaldos,
  origen: () => (miStock ? `tec:${miStock.nombre}` : ""),
  escanear: () => document.getElementById("miStockEscanearBtn").click(),
  alCambiar: () => { document.getElementById("miStockDevolverBtn").disabled = !miStockCanasta.items().length; },
});
// ---------- Camionetas (depósitos móviles) ----------
const miCamElegida = () => document.getElementById("miCamSelect").value;
const miCamSaldos = () => {
  const v = miCamElegida(), cam = (miStock && miStock.camionetas && miStock.camionetas[v]) || { tiene: {}, unidades: [] };
  const u = {};
  (cam.unidades || []).forEach((x) => { u[x.tracking] = { c: x.c, u: `veh:${v}` }; });
  return { ubic: { [`veh:${v}`]: cam.tiene || {} }, unidades: u };
};
const miCamCanasta = crearCanastaStock({
  cont: document.getElementById("miCamCanasta"),
  catalogo: miStockCatalogo, saldos: miCamSaldos,
  origen: () => (miCamElegida() ? `veh:${miCamElegida()}` : ""),
  escanear: () => document.getElementById("miCamEscanearBtn").click(),
  alCambiar: () => { document.getElementById("miCamTomarBtn").disabled = !miCamCanasta.items().length; },
});
function pintarCamionetas() {
  const cams = Object.keys((miStock && miStock.camionetas) || {}).sort((a, b) => a.localeCompare(b, "es"));
  const caja = document.getElementById("miCamCaja"), sel = document.getElementById("miCamSelect");
  caja.classList.toggle("hidden", !cams.length);
  // ¿Adónde vuelve lo que devuelvo? Depósito o una camioneta.
  const ad = document.getElementById("miStockAdonde"), adPrevio = ad.value;
  ad.innerHTML = '<option value="">Al depósito (lo confirma el depósito)</option>' + cams.map((v) => `<option value="${escapeHtml(v)}">Camioneta ${escapeHtml(v)} (queda ya)</option>`).join("");
  if (cams.includes(adPrevio)) ad.value = adPrevio;
  document.getElementById("miStockAdondeCaja").classList.toggle("hidden", !cams.length);
  if (!cams.length) return;
  let previa = sel.value;
  if (!previa) { try { previa = localStorage.getItem("stock_mi_camioneta") || ""; } catch (e) { previa = ""; } }
  sel.innerHTML = cams.map((v) => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join("");
  sel.value = cams.includes(previa) ? previa : cams[0];
  const a = miStock.articulos || {}, d = (c) => (a[c] || {}).d || c, cam = miStock.camionetas[sel.value] || { tiene: {}, unidades: [] };
  const tiene = Object.entries(cam.tiene || {}).filter(([, n]) => n > 0).sort((x, y) => d(x[0]).localeCompare(d(y[0]), "es"));
  const serDe = (c) => (cam.unidades || []).filter((u) => u.c === c).map((u) => u.tracking);
  document.getElementById("miCamTiene").innerHTML = tiene.length ? tiene.map(([c, n]) => `<div class="stk-linea stk-linea-cant"><div class="stk-linea-top"><div><b>${escapeHtml(d(c))}</b><small>${escapeHtml(c)}${serDe(c).length ? " · " + serDe(c).map(escapeHtml).join(" · ") : ""}</small></div><div class="stk-cant"><b style="font-size:16px;">${stkFmtN(n)}</b><button type="button" class="btn btn-secondary btn-small" style="width:auto;height:auto;padding:8px 10px;font-size:13px;" data-tomar="${escapeHtml(c)}">Tomar</button></div></div></div>`).join("")
    : '<p class="stk-ayuda">La camioneta está vacía.</p>';
  document.querySelectorAll("#miCamTiene [data-tomar]").forEach((b) => b.addEventListener("click", () => {
    const c = b.dataset.tomar;
    miCamCanasta.sumarUno(c, cam.tiene[c] || 0).then((r) => { if (r && (!r.ok || r.completo === false)) stkAviso(r.texto, r.ok ? "info" : "err"); });
  }));
  miCamCanasta.render();
  document.getElementById("miCamTomarBtn").disabled = !miCamCanasta.items().length;
}
